    --text: #4a4a6a;
    --text-light: #8888aa;
    --shadow: 0 4px 20px rgba(255, 107, 157, 0.12);
    --shadow-hover: 0 8px 32px rgba(255, 107, 157, 0.22);
    --radius: 16px;
    --radius-sm: 10px;
  }
  * { margin:0; padding:0; box-sizing:border-box; }
  body {
    font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
    background: var(--bg);
