// ==================== INIT ====================
function init() {
  populateDevFilter();
  renderGames(games);
}

function populateDevFilter() {
  const devs = [...new Set(games.map(g => g.developer))].sort();
  const sel = document.getElementById('filterDev');
  devs.forEach(d => {
    const opt = document.createElement('option');
    opt.value = d; opt.textContent = d;
    sel.appendChild(opt);
  });
}

function renderGames(gameList) {
  const grid = document.getElementById('gamesGrid');
  const noRes = document.getElementById('noResults');
  const count = document.getElementById('gameCount');

  grid.innerHTML = '';
  count.textContent = gameList.length;

  if (gameList.length === 0) {
    grid.style.display = 'none';
    noRes.style.display = 'block';
    return;
  }
  grid.style.display = 'grid';
  noRes.style.display = 'none';

  const colorGradients = [
    ['#ff6b9d','#ffa6c9'], ['#7ec8e3','#a0d8ef'], ['#c3aed6','#d5c8e4'],
    ['#ffe4b5','#fff0d5'], ['#98fb98','#b8fbb8'], ['#ffd700','#ffe44d'],
    ['#b0c4de','#cdd5e0'], ['#87ceeb','#a8daf0'], ['#e74c3c','#f09b95'],
    ['#fffacd','#fffde0'], ['#ffe4e1','#ffefed'], ['#a8d8ea','#cce5f2']
  ];

  gameList.forEach((game, i) => {
    const grad = colorGradients[i % colorGradients.length];
    const card = document.createElement('div');
    card.className = 'game-card';
    card.onclick = () => openModal(game);
    card.innerHTML = `
      <div class="game-card-image" style="background:linear-gradient(135deg, ${grad[0]}, ${grad[1]})">
        <span class="placeholder-icon">🎮</span>
        <span class="year-badge">${game.year}</span>
      </div>
      <div class="game-card-body">
        <h3>${game.title}</h3>
        <p class="title-jp">${game.titleJp}</p>
        <div class="meta">
          <span class="tag tag-dev">🏢 ${game.developer}</span>
          ${game.platforms.map(p => `<span class="tag tag-plat">${p}</span>`).join('')}
        </div>
        <p class="desc">${game.desc}</p>
      </div>
    `;
    grid.appendChild(card);
  });
}

// ==================== FILTERS ====================
function applyFilters() {
  const searchTerm = document.getElementById('searchInput').value.toLowerCase().trim();
  const year = document.getElementById('filterYear').value;
  const platform = document.getElementById('filterPlatform').value;
  const dev = document.getElementById('filterDev').value;

  let filtered = games;

  if (searchTerm) {
    filtered = filtered.filter(g =>
      g.title.toLowerCase().includes(searchTerm) ||
      g.titleJp.includes(searchTerm) ||
      g.developer.toLowerCase().includes(searchTerm) ||
      g.desc.toLowerCase().includes(searchTerm) ||
      g.characters.some(c => c.name.includes(searchTerm))
    );
  }
  if (year) filtered = filtered.filter(g => g.year === parseInt(year));
  if (platform) filtered = filtered.filter(g => g.platforms.includes(platform));
  if (dev) filtered = filtered.filter(g => g.developer === dev);

  renderGames(filtered);
}

function resetFilters() {
  document.getElementById('searchInput').value = '';
  document.getElementById('filterYear').value = '';
  document.getElementById('filterPlatform').value = '';
  document.getElementById('filterDev').value = '';
  renderGames(games);
}

// Live search
document.getElementById('searchInput').addEventListener('input', applyFilters);
document.getElementById('filterYear').addEventListener('change', applyFilters);
document.getElementById('filterPlatform').addEventListener('change', applyFilters);
document.getElementById('filterDev').addEventListener('change', applyFilters);

// ==================== MODAL ====================
function openModal(game) {
  document.getElementById('modalTitle').textContent = game.title;
  document.getElementById('modalTitleJp').textContent = game.titleJp;
  document.getElementById('modalBody').innerHTML = buildModalContent(game);
  document.getElementById('modalOverlay').classList.add('active');
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  document.getElementById('modalOverlay').classList.remove('active');
  document.body.style.overflow = '';
}

function closeModalOutside(e) {
  if (e.target === document.getElementById('modalOverlay')) closeModal();
}

document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeModal();
});

