      <div class="cg-gallery">
        ${Array.from({length: Math.min(6, game.cgCount)}, (_, i) => `
          <div class="cg-item" title="CG #${i+1}">🎨</div>
        `).join('')}
        ${game.cgCount > 6 ? `<div class="cg-item" style="font-size:1.2rem; background:var(--pink-light)">+${game.cgCount - 6}<br>更多</div>` : ''}
      </div>
