{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>🌸 Galgame 年鉴 2020-2025 — 阿罗娜的恋爱指南</title>
<style>
  :root {
    --pink: #ff6b9d;
    --pink-light: #ffe0ec;
    --blue: #7ec8e3;
    --blue-light: #e3f4fc;
    --purple: #c3aed6;
    --purple-deep: #9b72cf;
    --yellow: #fff3cd;
    --bg: #faf8ff;
    --card-bg: #ffffff;
    --text: #4a4a6a;
    --text-light: #8888aa;
    --shadow: 0 4px 20px rgba(255, 107, 157, 0.12);
    --shadow-hover: 0 8px 32px rgba(255, 107, 157, 0.22);
    --radius: 16px;
    --radius-sm: 10px;
    --accent-gradient: linear-gradient(135deg, #ff6b9d, #c471f5, #7ec8e3);
  }
  * { margin:0; padding:0; box-sizing:border-box; }
  body {
    font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
    background: #0a0a1a;
    color: #e0d8f0;
    line-height: 1.6;
    min-height: 100vh;
    overflow-x: hidden;
    cursor: default;
  }

  /* =============== SAKURA PETALS =============== */
  .petal-container {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%;
    pointer-events: none; z-index: 9999;
  }
  .petal {
    position: absolute; top: -10%;
    font-size: 1.2rem;
    animation: fall linear forwards;
    pointer-events: none;
    opacity: 0.7;
  }
  @keyframes fall {
    0% { transform: translateY(0) rotate(0deg) translateX(0); opacity: 0.9; }
    50% { transform: translateY(50vh) rotate(180deg) translateX(60px); opacity: 0.7; }
    100% { transform: translateY(110vh) rotate(360deg) translateX(-30px); opacity: 0; }
  }

  /* =============== CLICK RIPPLE =============== */
  .ripple {
    position: fixed;
    border-radius: 50%;
    pointer-events: none;
    z-index: 10000;
    animation: rippleOut 0.8s ease-out forwards;
  }
  @keyframes rippleOut {
    0% { width:0; height:0; opacity:1; border-width:4px; }
    100% { width:120px; height:120px; opacity:0; border-width:1px; margin-left:-60px; margin-top:-60px; }
  }

  /* =============== SPARKLE TRAIL =============== */
  .sparkle {
    position: fixed; pointer-events: none; z-index: 10001;
    font-size: 1rem;
    animation: sparkleFade 0.7s ease-out forwards;
  }
  @keyframes sparkleFade {
    0% { opacity:1; transform: scale(1) translateY(0); }
    100% { opacity:0; transform: scale(0.3) translateY(-30px); }
  }

  /* =============== CURSOR GLOW =============== */
  .cursor-glow {
    position: fixed; pointer-events: none; z-index: 9998;
    width: 200px; height: 200px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(255,107,157,0.12) 0%, transparent 70%);
    transform: translate(-50%, -50%);
    transition: opacity 0.3s;
  }

  /* =============== STARFIELD BG =============== */
  .stars-bg { position: fixed; top:0; left:0; width:100%; height:100%; pointer-events:none; z-index:0; }
  .star {
    position: absolute;
    background: #fff;
    border-radius: 50%;
    animation: twinkle var(--dur) ease-in-out infinite;
    animation-delay: var(--delay);
  }
  @keyframes twinkle {
    0%,100% { opacity: 0.3; transform: scale(1); }
    50% { opacity: 1; transform: scale(1.5); }
  }

  /* =============== HEADER =============== */
  header {
    background: linear-gradient(135deg, #1a0a2e 0%, #2d1b4e 30%, #1a0a3e 60%, #0d1b2a 100%);
    padding: 32px 20px 24px;
    text-align: center;
    position: sticky; top: 0; z-index: 100;
    box-shadow: 0 4px 30px rgba(197, 113, 245, 0.25);
    border-bottom: 2px solid rgba(255,107,157,0.2);
  }
  .header-inner { position: relative; z-index: 2; }
  header h1 {
    background: linear-gradient(135deg, #ff6b9d, #c471f5, #7ec8e3);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    background-clip: text;
    font-size: 2.2rem; letter-spacing: 3px;
    text-shadow: none;
    font-weight: 900;
  }
  header .subtitle {
    color: rgba(220,200,255,0.85);
    font-size: 0.95rem;
    margin-top: 6px;
  }
  .header-char {
    display: inline-block;
    animation: headerBounce 2s ease-in-out infinite;
    font-size: 1.6rem;
  }
  @keyframes headerBounce {
    0%,100% { transform: translateY(0); }
    30% { transform: translateY(-10px) rotate(5deg); }
    60% { transform: translateY(0) rotate(-3deg); }
  }

  /* =============== CONTAINER =============== */
  .container { max-width: 1320px; margin: 0 auto; padding: 0 20px; position: relative; z-index: 1; }

  /* =============== SEARCH & FILTERS =============== */
  .search-section {
    background: rgba(30,20,50,0.9);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255,107,157,0.2);
    border-radius: var(--radius);
    padding: 24px;
    margin: -20px auto 28px;
    max-width: 1320px;
    box-shadow: 0 8px 32px rgba(197,113,245,0.15);
    position: relative;
    z-index: 50;
  }
  .search-section::before {
    content: ''; position: absolute; top:-1px; left:20px; right:20px;
    height:2px;
    background: linear-gradient(90deg, transparent, rgba(255,107,157,0.5), rgba(126,200,227,0.5), transparent);
  }
  .search-row {
    display: flex; gap: 12px; flex-wrap: wrap; align-items: center;
  }
  .search-input {
    flex: 1; min-width: 220px;
    padding: 12px 18px;
    border: 2px solid rgba(255,107,157,0.3);
    border-radius: 30px;
    font-size: 1rem;
    outline: none;
    transition: all 0.4s;
    background: rgba(20,10,40,0.8);
    color: #e0d8f0;
  }
  .search-input::placeholder { color: rgba(200,180,220,0.5); }
  .search-input:focus {
    border-color: #ff6b9d;
    box-shadow: 0 0 20px rgba(255,107,157,0.2), 0 0 0 4px rgba(255,107,157,0.08);
  }
  .filter-select {
    padding: 12px 16px;
    border: 2px solid rgba(255,107,157,0.3);
    border-radius: 30px;
    font-size: 0.95rem;
    background: rgba(20,10,40,0.8);
    cursor: pointer;
    outline: none;
    min-width: 130px;
    color: #e0d8f0;
    transition: all 0.3s;
  }
  .filter-select:focus { border-color: #c471f5; box-shadow: 0 0 12px rgba(196,113,245,0.2); }
  .btn {
    padding: 12px 24px;
    border: none; border-radius: 30px;
    font-size: 0.95rem; cursor: pointer;
    transition: all 0.35s cubic-bezier(0.4,0,0.2,1);
    font-weight: 700;
    position: relative; overflow: hidden;
  }
  .btn::after {
    content: ''; position: absolute; top:50%; left:50%;
    width:0; height:0; border-radius: 50%;
    background: rgba(255,255,255,0.2);
    transform: translate(-50%,-50%);
    transition: width 0.6s, height 0.6s;
  }
  .btn:active::after { width:300px; height:300px; }
  .btn-primary {
    background: linear-gradient(135deg, #ff6b9d, #c471f5);
    color: #fff;
    box-shadow: 0 4px 15px rgba(255,107,157,0.35);
  }
  .btn-primary:hover { transform: translateY(-3px); box-shadow: 0 8px 25px rgba(196,113,245,0.5); }
  .btn-reset {
    background: rgba(255,255,255,0.06);
    color: #c8b8e0;
    border: 1px solid rgba(255,255,255,0.1);
  }
  .btn-reset:hover { border-color: #c471f5; color: #d4c4f0; background: rgba(196,113,245,0.1); }
  .result-count {
    margin-top: 12px; font-size: 0.9rem;
    color: rgba(200,180,220,0.7);
  }
  .result-count span { color: #ff6b9d; font-weight: 700; }

  /* =============== GAME CARDS =============== */
  .games-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
    gap: 24px;
    padding-bottom: 40px;
  }
  .game-card {
    background: rgba(30,20,50,0.85);
    backdrop-filter: blur(8px);
    border-radius: var(--radius);
    overflow: hidden;
    box-shadow: 0 4px 16px rgba(0,0,0,0.3);
    cursor: pointer;
    transition: all 0.4s cubic-bezier(0.4,0,0.2,1);
    border: 1px solid rgba(255,107,157,0.1);
    position: relative;
  }
  .game-card::before {
    content: '';
    position: absolute; inset: -2px;
    border-radius: var(--radius);
    background: linear-gradient(135deg, transparent, rgba(255,107,157,0.3), rgba(126,200,227,0.3), transparent);
    opacity: 0;
    transition: opacity 0.4s;
    z-index: -1;
    filter: blur(4px);
  }
  .game-card:hover::before { opacity: 1; }
  .game-card:hover {
    transform: translateY(-8px) scale(1.02);
    box-shadow: 0 16px 40px rgba(196,113,245,0.25);
    border-color: rgba(255,107,157,0.4);
  }
  .game-card-image {
    height: 210px;
    position: relative; overflow: hidden;
  }
  .card-grad-0 { background: linear-gradient(135deg, #ff6b9d, #ffa6c9); }
  .card-grad-1 { background: linear-gradient(135deg, #7ec8e3, #a0d8ef); }
  .card-grad-2 { background: linear-gradient(135deg, #c471f5, #d5b8f0); }
  .card-grad-3 { background: linear-gradient(135deg, #f0a050, #f5d0a0); }
  .card-grad-4 { background: linear-gradient(135deg, #50c878, #a0e8c0); }
  .card-grad-5 { background: linear-gradient(135deg, #ff6b9d, #ffd700); }
  .card-grad-6 { background: linear-gradient(135deg, #7080d0, #b0c0f0); }
  .card-grad-7 { background: linear-gradient(135deg, #d06090, #e0a0c0); }
  .card-grad-8 { background: linear-gradient(135deg, #40a0c0, #80d0e0); }
  .card-grad-9 { background: linear-gradient(135deg, #c060e0, #e0a0f0); }
  .card-grad-10 { background: linear-gradient(135deg, #e06070, #f0a0b0); }
  .card-grad-11 { background: linear-gradient(135deg, #60a0c0, #a0d0e0); }
  .card-grad-12 { background: linear-gradient(135deg, #a060d0, #c0a0e0); }
  .card-grad-13 { background: linear-gradient(135deg, #f08060, #f5c0a0); }
  .card-grad-14 { background: linear-gradient(135deg, #60c090, #a0e0c0); }
  .card-grad-15 { background: linear-gradient(135deg, #d0a060, #e0c090); }
  .card-grad-16 { background: linear-gradient(135deg, #8060d0, #b0a0e0); }
  .card-grad-17 { background: linear-gradient(135deg, #c07090, #e0b0c0); }

  .game-card-image .placeholder-icon {
    font-size: 4.5rem;
    transition: transform 0.5s, opacity 0.3s;
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
  }
  .game-card:hover .placeholder-icon {
    transform: translate(-50%, -50%) scale(1.2);
  }
  .game-card-image .year-badge {
    position: absolute; top: 14px; right: 14px;
    background: rgba(0,0,0,0.5);
    backdrop-filter: blur(6px);
    color: #fff;
    padding: 5px 14px;
    border-radius: 20px;
    font-size: 0.8rem; font-weight: 700;
    border: 1px solid rgba(255,255,255,0.2);
    transition: all 0.3s;
  }
  .game-card:hover .year-badge {
    background: rgba(255,107,157,0.7);
    border-color: rgba(255,107,157,0.6);
  }
  .game-card-body { padding: 20px; }
  .game-card-body h3 {
    font-size: 1.15rem;
    margin-bottom: 4px;
    color: #f0e8ff;
  }
  .game-card-body .title-jp {
    font-size: 0.8rem; color: rgba(200,180,220,0.7); margin-bottom: 10px;
  }
  .game-card-body .meta {
    display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 10px;
  }
  .game-card-body .tag {
    padding: 4px 12px; border-radius: 14px;
    font-size: 0.75rem; font-weight: 700;
  }
  .tag-dev { background: rgba(126,200,227,0.2); color: #7ec8e3; border: 1px solid rgba(126,200,227,0.2); }
  .tag-plat { background: rgba(255,211,0,0.15); color: #ffd54f; border: 1px solid rgba(255,211,0,0.2); }
  .game-card-body .desc {
    font-size: 0.85rem; color: rgba(200,180,220,0.7);
    display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
    overflow: hidden;
  }

  /* =============== MODAL =============== */
  .modal-overlay {
    display: none;
    position: fixed; top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0,0,0,0.7);
    z-index: 200;
    justify-content: center; align-items: flex-start;
    padding: 20px;
    overflow-y: auto;
    backdrop-filter: blur(4px);
  }
  .modal-overlay.active { display: flex; }
  .modal {
    background: rgba(25,15,40,0.97);
    backdrop-filter: blur(16px);
    border-radius: var(--radius);
    max-width: 900px; width: 100%;
    margin: 20px 0;
    box-shadow: 0 20px 60px rgba(0,0,0,0.5), 0 0 40px rgba(196,113,245,0.15);
    animation: slideUp 0.4s cubic-bezier(0.34,1.56,0.64,1);
    border: 1px solid rgba(196,113,245,0.2);
  }
  @keyframes slideUp {
    from { opacity:0; transform:translateY(50px) scale(0.95); }
    to { opacity:1; transform:translateY(0) scale(1); }
  }
  .modal-header {
    padding: 24px 28px;
    background: linear-gradient(135deg, rgba(255,107,157,0.1), rgba(196,113,245,0.1));
    border-radius: var(--radius) var(--radius) 0 0;
    display: flex; justify-content: space-between; align-items: flex-start;
    border-bottom: 1px solid rgba(255,107,157,0.15);
  }
  .modal-header h2 { font-size: 1.6rem; color: #f0e8ff; }
  .modal-header .title-jp { font-size: 0.85rem; color: rgba(200,180,220,0.6); }
  .modal-close {
    background: none; border: 1px solid rgba(255,255,255,0.15);
    font-size: 1.8rem; cursor: pointer;
    color: rgba(200,180,220,0.7); padding: 4px 12px; border-radius: 50%;
    transition: all 0.3s; line-height: 1;
  }
  .modal-close:hover { color: #ff6b9d; border-color: #ff6b9d; background: rgba(255,107,157,0.1); }
  .modal-body { padding: 24px 28px; }
  .modal-body section { margin-bottom: 24px; }
  .modal-body section h3 {
    font-size: 1.15rem;
    background: linear-gradient(135deg, #ff6b9d, #c471f5);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 2px solid rgba(255,107,157,0.2);
    display: flex; align-items: center; gap: 8px;
  }
  .modal-body .meta-info {
    display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 16px;
  }
  .meta-item {
    padding: 6px 16px; border-radius: 20px;
    font-size: 0.85rem;
    background: rgba(255,107,157,0.08);
    border: 1px solid rgba(255,107,157,0.15);
  }
  .meta-item strong { color: #ff6b9d; }

  /* Characters */
  .char-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 14px;
  }
  .char-card {
    display: flex; gap: 14px;
    background: rgba(30,20,50,0.6);
    padding: 14px; border-radius: var(--radius-sm);
    transition: all 0.3s;
    align-items: flex-start;
    border: 1px solid rgba(255,107,157,0.08);
  }
  .char-card:hover {
    background: rgba(196,113,245,0.1);
    border-color: rgba(196,113,245,0.25);
    transform: translateY(-2px);
  }
  .char-avatar {
    width: 72px; height: 72px; border-radius: 50%;
    background: linear-gradient(135deg, #c471f5, #ff6b9d);
    display: flex; align-items: center; justify-content: center;
    font-size: 2rem; flex-shrink: 0;
    border: 2px solid rgba(255,107,157,0.3);
  }
  .char-info h4 { font-size: 0.95rem; margin-bottom: 2px; color: #f0e8ff; }
  .char-info .cv { font-size: 0.75rem; color: rgba(200,180,220,0.6); margin-bottom: 4px; }
  .char-info p { font-size: 0.8rem; color: rgba(200,180,220,0.75); line-height: 1.5; }

  /* CG Gallery */
  .cg-gallery {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
    gap: 12px;
  }
  .cg-item {
    aspect-ratio: 16/10;
    background: linear-gradient(135deg, rgba(126,200,227,0.15), rgba(196,113,245,0.15));
    border: 1px solid rgba(126,200,227,0.2);
    border-radius: var(--radius-sm);
    display: flex; align-items: center; justify-content: center;
    font-size: 2.8rem; transition: all 0.3s; cursor: pointer;
  }
  .cg-item:hover {
    transform: scale(1.06);
    border-color: rgba(196,113,245,0.5);
    box-shadow: 0 4px 16px rgba(196,113,245,0.2);
  }

  /* Resource */
  .resource-links {
    display: flex; flex-wrap: wrap; gap: 10px;
  }
  .resource-link {
    display: inline-flex; align-items: center; gap: 6px;
    padding: 10px 20px;
    border-radius: 30px;
    text-decoration: none;
    font-size: 0.9rem; font-weight: 700;
    transition: all 0.35s cubic-bezier(0.4,0,0.2,1);
  }
  .res-official { background: linear-gradient(135deg, #ff6b9d, #f06292); color: #fff; }
  .res-official:hover { transform: translateY(-2px); box-shadow: 0 6px 20px rgba(255,107,157,0.4); }
  .res-vndb { background: rgba(126,200,227,0.2); color: #7ec8e3; border: 1px solid rgba(126,200,227,0.3); }
  .res-vndb:hover { background: rgba(126,200,227,0.3); transform: translateY(-2px); }
  .res-steam { background: #1b2838; color: #fff; border: 1px solid #2a475e; }
  .res-steam:hover { background: #2a475e; transform: translateY(-2px); }
  .res-store { background: rgba(255,211,0,0.15); color: #ffd54f; border: 1px solid rgba(255,211,0,0.3); }
  .res-store:hover { background: rgba(255,211,0,0.25); transform: translateY(-2px); }
  .res-resource { background: rgba(196,113,245,0.15); color: #c471f5; border: 1px solid rgba(196,113,245,0.3); }
  .res-resource:hover { background: rgba(196,113,245,0.25); transform: translateY(-2px); }

  /* =============== RESOURCE SITES SECTION =============== */
  .resource-sites {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 16px;
    margin-top: 40px;
    padding: 0 20px 40px;
  }
  .resource-site-card {
    background: rgba(30,20,50,0.8);
    border: 1px solid rgba(196,113,245,0.15);
    border-radius: var(--radius);
    padding: 20px;
    transition: all 0.35s;
    text-decoration: none;
    color: #e0d8f0;
    display: block;
    position: relative; overflow: hidden;
  }
  .resource-site-card:hover {
    border-color: rgba(196,113,245,0.4);
    transform: translateY(-4px);
    box-shadow: 0 8px 24px rgba(196,113,245,0.2);
  }
  .resource-site-card .site-icon { font-size: 2rem; margin-bottom: 8px; }
  .resource-site-card h4 { font-size: 1.05rem; color: #f0e8ff; margin-bottom: 4px; }
  .resource-site-card .site-url { font-size: 0.78rem; color: rgba(200,180,220,0.5); margin-bottom: 6px; }
  .resource-site-card p { font-size: 0.82rem; color: rgba(200,180,220,0.7); line-height: 1.5; }
  .resource-sites-title {
    text-align: center; margin-top: 48px; margin-bottom: 24px;
    font-size: 1.5rem;
    background: linear-gradient(135deg, #ff6b9d, #c471f5, #7ec8e3);
    -webkit-background-clip: text; -webkit-text-fill-color: transparent;
    background-clip: text;
    font-weight: 900;
  }

  /* ============ FLOATING QUICK-NAV ============ */
  .quick-nav {
    position: fixed; bottom: 24px; right: 24px;
    z-index: 150;
    display: flex; flex-direction: column; gap: 10px;
  }
  .quick-nav-btn {
    width: 48px; height: 48px;
    border-radius: 50%;
    border: 1px solid rgba(196,113,245,0.3);
    background: rgba(30,20,50,0.9);
    backdrop-filter: blur(6px);
    color: #c8b8e0;
    font-size: 1.2rem;
    cursor: pointer;
    transition: all 0.3s;
    display: flex; align-items: center; justify-content: center;
  }
  .quick-nav-btn:hover {
    background: rgba(196,113,245,0.2);
    border-color: #c471f5;
    color: #f0e8ff;
    transform: scale(1.1);
    box-shadow: 0 4px 16px rgba(196,113,245,0.25);
  }

  /* =============== FOOTER =============== */
  footer {
    text-align: center; padding: 32px;
    color: rgba(200,180,220,0.5); font-size: 0.85rem;
    background: rgba(20,10,30,0.8);
    border-top: 1px solid rgba(196,113,245,0.1);
    position: relative; z-index: 1;
  }
  footer .heart { color: #ff6b9d; }

  /* =============== RESPONSIVE =============== */
  @media (max-width: 768px) {
    header h1 { font-size: 1.4rem; }
    .search-row { flex-direction: column; }
    .filter-select, .btn { width: 100%; }
    .games-grid { grid-template-columns: 1fr; }
    .char-grid { grid-template-columns: 1fr; }
    .cg-gallery { grid-template-columns: repeat(2, 1fr); }
    .resource-sites { grid-template-columns: 1fr; }
    .modal { margin: 10px 0; }
    .modal-body { padding: 16px; }
  }

  /* =============== NO RESULTS =============== */
  .no-results {
    text-align: center; padding: 60px 20px;
    color: rgba(200,180,220,0.5);
  }
  .no-results .icon { font-size: 4rem; margin-bottom: 12px; }
</style>
</head>
<body>

<!-- STARFIELD -->
<div class="stars-bg" id="starsBg"></div>

<!-- CURSOR GLOW -->
<div class="cursor-glow" id="cursorGlow"></div>

<!-- SAKURA PETALS -->
<div class="petal-container" id="petalContainer"></div>

<!-- ==================== HEADER ==================== -->
<header>
  <div class="header-inner">
    <h1><span class="header-char">🌸</span> Galgame 年鉴 2020-2025</h1>
    <p class="subtitle">✨ 阿罗娜精心整理的恋爱冒险指南！涵盖20+部精品 Galgame · 持续更新中 ✨</p>
  </div>
</header>

<!-- ==================== SEARCH ==================== -->
<div class="container">
  <div class="search-section">
    <div class="search-row">
      <input type="text" class="search-input" id="searchInput"
             placeholder="🔍 搜索游戏名、开发商、角色名、CV……">
      <select class="filter-select" id="filterYear">
        <option value="">📅 全部年份</option>
        <option value="2020">2020</option><option value="2021">2021</option>
        <option value="2022">2022</option><option value="2023">2023</option>
        <option value="2024">2024</option><option value="2025">2025</option>
      </select>
      <select class="filter-select" id="filterPlatform">
        <option value="">💻 全部平台</option>
        <option value="PC">PC</option><option value="Switch">Switch</option>
        <option value="PS4">PS4</option><option value="PS5">PS5</option>
        <option value="Mobile">iOS/Android</option>
      </select>
      <select class="filter-select" id="filterDev">
        <option value="">🏢 全部开发商</option>
      </select>
      <button class="btn btn-primary" onclick="applyFilters()">🔍 搜索</button>
      <button class="btn btn-reset" onclick="resetFilters()">🔄 重置</button>
    </div>
    <p class="result-count">共收录 <span id="gameCount">0</span> 部作品</p>
  </div>

  <!-- GAME GRID -->
  <div class="games-grid" id="gamesGrid"></div>
  <div class="no-results" id="noResults" style="display:none">
    <div class="icon">😿</div>
    <p>呜哇……没有找到匹配的 Galgame 呢～</p>
    <p style="font-size:0.85rem">老师换个关键词试试？阿罗娜会加油完善的！</p>
  </div>
</div>

<!-- RESOURCE SITES -->
<h2 class="resource-sites-title">🔗 推荐资源站点</h2>
<div class="resource-sites" id="resourceSites"></div>

<!-- ==================== MODAL ==================== -->
<div class="modal-overlay" id="modalOverlay" onclick="closeModalOutside(event)">
  <div class="modal" id="modal">
    <div class="modal-header">
      <div>
        <h2 id="modalTitle"></h2>
        <span class="title-jp" id="modalTitleJp"></span>
      </div>
      <button class="modal-close" onclick="closeModal()">✕</button>
    </div>
    <div class="modal-body" id="modalBody"></div>
  </div>
</div>

<!-- FLOATING QUICK NAV -->
