// ==================== STARFIELD ====================
(function(){
  const bg = document.getElementById('starsBg');
  for(let i=0; i<80; i++){
    const star = document.createElement('div');
    star.className = 'star';
    star.style.left = Math.random()*100+'%';
    star.style.top = Math.random()*100+'%';
    star.style.width = (1+Math.random()*2.5)+'px';
    star.style.height = star.style.width;
    star.style.setProperty('--dur', (2+Math.random()*4)+'s');
    star.style.setProperty('--delay', Math.random()*4+'s');
    bg.appendChild(star);
  }
})();

// ==================== SAKURA PETALS ====================
const petalEmojis = ['🌸','💮','🌺','✿','❀','🌷','💐'];
let petalsActive = true;
function spawnPetal(){
  if(!petalsActive) return;
  const p = document.createElement('div');
  p.className = 'petal';
  p.textContent = petalEmojis[Math.floor(Math.random()*petalEmojis.length)];
  p.style.left = Math.random()*98+'%';
  p.style.fontSize = (0.8+Math.random()*1.5)+'rem';
  p.style.animationDuration = (8+Math.random()*10)+'s';
  p.style.animationDelay = Math.random()*3+'s';
  document.getElementById('petalContainer').appendChild(p);
  setTimeout(()=>p.remove(), 16000);
}
setInterval(spawnPetal, 1800);
for(let i=0;i<6;i++) setTimeout(spawnPetal, i*400);

function togglePetals(){
  petalsActive = !petalsActive;
  document.getElementById('petalToggle').textContent = petalsActive ? '🌸' : '🍂';
  if(!petalsActive) document.getElementById('petalContainer').innerHTML = '';
}

// ==================== CURSOR GLOW ====================
const cursorGlow = document.getElementById('cursorGlow');
let mouseX = -999, mouseY = -999;
document.addEventListener('mousemove', e=>{
  mouseX = e.clientX; mouseY = e.clientY;
  cursorGlow.style.left = mouseX+'px';
  cursorGlow.style.top = mouseY+'px';
});
document.addEventListener('mouseleave', ()=> cursorGlow.style.opacity='0');
document.addEventListener('mouseenter', ()=> cursorGlow.style.opacity='1');

// ==================== CLICK RIPPLE ====================
document.addEventListener('click', e=>{
  // Ripple
  const ripple = document.createElement('div');
  ripple.className = 'ripple';
  ripple.style.left = e.clientX+'px';
  ripple.style.top = e.clientY+'px';
  ripple.style.border = '2px solid '+['#ff6b9d','#c471f5','#7ec8e3','#ffd54f'][Math.floor(Math.random()*4)];
  document.body.appendChild(ripple);
  setTimeout(()=>ripple.remove(), 800);

  // Sparkles
  for(let i=0;i<6;i++){
    const sp = document.createElement('div');
    sp.className = 'sparkle';
    sp.textContent = ['✨','💫','⭐','🌟','💖','♪'][i];
    sp.style.left = (e.clientX + (Math.random()-0.5)*60)+'px';
    sp.style.top = (e.clientY + (Math.random()-0.5)*60)+'px';
    sp.style.animationDuration = (0.5+Math.random()*0.8)+'s';
    document.body.appendChild(sp);
    setTimeout(()=>sp.remove(), 800);
  }
});

