  },
  {
    icon:"🦊", name:"稻荷GAL", url:"https://inarigal.com/",
    desc:"免费Galgame资源下载分享社区，收录丰富，更新活跃的新兴平台。"
  },
  {
    icon:"🌙", name:"月幕Galgame", url:"https://www.ymgal.games/",
    desc:"属于中国的美少女游戏综合交流平台——资讯、评测、Wiki、CG、表情包全覆盖。"
  },
  {
    icon:"✨", name:"Singureo", url:"https://www.limulu.moe/",
    desc:"简洁美观人性化的Galgame资源站，贯彻Astro现代化设计理念。"
  },
  {
    icon:"🎮", name:"TouchGal", url:"https://www.touchgal.us/",
    desc:"Galgame资源下载站点，收录众多汉化作品，社区氛围活跃。"
  }
];

// ==================== INIT ====================
function init(){
  populateDevFilter();
  renderGames(games);
  renderResourceSites();
}

function populateDevFilter(){
  const devs = [...new Set(games.map(g=>g.developer))].sort();
  const sel = document.getElementById('filterDev');
  devs.forEach(d=>{
    const o = document.createElement('option');
    o.value=d; o.textContent=d;
    sel.appendChild(o);
  });
}

function renderResourceSites(){
  const container = document.getElementById('resourceSites');
  resourceSites.forEach(site=>{
    const card = document.createElement('a');
    card.className = 'resource-site-card';
    card.href = site.url;
    card.target = '_blank';
    card.rel = 'noopener';
    card.innerHTML = `
      <div class="site-icon">${site.icon}</div>
      <h4>${site.name}</h4>
      <div class="site-url">${site.url.replace('https://','')}</div>
      <p>${site.desc}</p>`;
    container.appendChild(card);
  });
}

function renderGames(gameList){
  const grid = document.getElementById('gamesGrid');
  const noRes = document.getElementById('noResults');
  const count = document.getElementById('gameCount');
  grid.innerHTML = '';
  count.textContent = gameList.length;

  if(gameList.length===0){
    grid.style.display='none'; noRes.style.display='block'; return;
  }
  grid.style.display='grid'; noRes.style.display='none';

  gameList.forEach((game,i)=>{
    const card = document.createElement('div');
    card.className = 'game-card';
    card.onclick = ()=>openModal(game);
    card.innerHTML = `
      <div class="game-card-image card-grad-${i%18}">
        <span class="placeholder-icon">🎮</span>
        <span class="year-badge">${game.year}</span>
      </div>
      <div class="game-card-body">
        <h3>${game.title}</h3>
        <p class="title-jp">${game.titleJp}</p>
        <div class="meta">
          <span class="tag tag-dev">🏢 ${game.developer}</span>
          ${game.platforms.map(p=>`<span class="tag tag-plat">${p}</span>`).join('')}
        </div>
        <p class="desc">${game.desc}</p>
      </div>`;
    grid.appendChild(card);
  });
}

// ==================== FILTERS ====================
function applyFilters(){
  const search = document.getElementById('searchInput').value.toLowerCase().trim();
  const year = document.getElementById('filterYear').value;
  const plat = document.getElementById('filterPlatform').value;
  const dev = document.getElementById('filterDev').value;
  let f = games;
  if(search) f=f.filter(g=>g.title.toLowerCase().includes(search)||g.titleJp.includes(search)||g.developer.toLowerCase().includes(search)||g.desc.toLowerCase().includes(search)||g.characters.some(c=>c.name.includes(search)||c.cv.includes(search)||c.desc.includes(search)));
  if(year) f=f.filter(g=>g.year===parseInt(year));
  if(plat) f=f.filter(g=>g.platforms.includes(plat));
  if(dev) f=f.filter(g=>g.developer===dev);
  renderGames(f);
}
function resetFilters(){
  document.getElementById('searchInput').value='';
  document.getElementById('filterYear').value='';
  document.getElementById('filterPlatform').value='';
  document.getElementById('filterDev').value='';
  renderGames(games);
}
document.getElementById('searchInput').addEventListener('input',applyFilters);
document.getElementById('filterYear').addEventListener('change',applyFilters);
document.getElementById('filterPlatform').addEventListener('change',applyFilters);
document.getElementById('filterDev').addEventListener('change',applyFilters);

// ==================== MODAL ====================
function openModal(game){
  document.getElementById('modalTitle').textContent=game.title;
  document.getElementById('modalTitleJp').textContent=game.titleJp;
  document.getElementById('modalBody').innerHTML=buildModal(game);
  document.getElementById('modalOverlay').classList.add('active');
  document.body.style.overflow='hidden';
}
function closeModal(){
  document.getElementById('modalOverlay').classList.remove('active');
  document.body.style.overflow='';
}
function closeModalOutside(e){
  if(e.target===document.getElementById('modalOverlay')) closeModal();
}
document.addEventListener('keydown',e=>{if(e.key==='Escape') closeModal();});

function buildModal(game){
  let h = `<div class="meta-info">
    <span class="meta-item">📅 <strong>发售:</strong> ${game.year}年</span>
    <span class="meta-item">🏢 <strong>开发商:</strong> ${game.developer}</span>
    <span class="meta-item">💻 <strong>平台:</strong> ${game.platforms.join(' / ')}</span>
    <span class="meta-item">🖼️ <strong>CG:</strong> ${game.cgCount}+</span>
  </div>`;
  h+=`<section><h3>📖 背景说明</h3><p style="white-space:pre-line;line-height:1.9;">${game.background}</p></section>`;
  h+='<section><h3>👥 人物简介</h3><div class="char-grid">';
  game.characters.forEach(c=>{
    h+=`<div class="char-card"><div class="char-avatar">🎭</div><div class="char-info"><h4>${c.name}</h4><p class="cv">🎙️ CV: ${c.cv}</p><p>${c.desc}</p></div></div>`;
  });
  h+='</div></section>';
  h+=`<section><h3>🖼️ 官方CG (共${game.cgCount}张)</h3><p style="font-size:0.85rem;color:rgba(200,180,220,0.5);margin-bottom:12px;">⚠️ CG图片因版权原因未内嵌，请通过下方资源链接访问官方站点查看～</p><div class="cg-gallery">`;
  for(let i=0;i<Math.min(6,game.cgCount);i++) h+=`<div class="cg-item">🎨</div>`;
  if(game.cgCount>6) h+=`<div class="cg-item" style="font-size:1.2rem;background:rgba(196,113,245,0.15)">+${game.cgCount-6}<br>更多</div>`;
  h+='</div></section>';
  h+='<section><h3>🔗 资源获取途径</h3><div class="resource-links">';
  const tMap={official:'res-official',steam:'res-steam',vndb:'res-vndb',store:'res-store',resource:'res-resource'};
  game.resources.forEach(r=>{h+=`<a href="${r.url}" target="_blank" rel="noopener" class="resource-link ${tMap[r.type]||'res-store'}">${r.label}</a>`;});
  h+=`<div style="margin-top:14px;padding:14px;background:rgba(255,211,0,0.08);border:1px solid rgba(255,211,0,0.2);border-radius:var(--radius-sm);font-size:0.85rem;color:rgba(255,211,0,0.8);">
    💡 <strong>阿罗娜的小提示：</strong>正版渠道优先推荐 Steam / 官网购买！部分游戏在 DLsite、Getchu、FANZA 等平台有售。中文资源可参考 Hikarinagi / NekoGAL / 稻荷GAL / Singureo 等站点。
  </div></section>`;
  return h;
}

init();
</script>
</body>
</html>
